import sys, json, re, math
from fractions import Fraction
from itertools import combinations, product

MAXBYTES = 8388608
NUMERIC = {"TIME", "SIZE", "COUNT"}
ALLTYPES = {"TIME", "SIZE", "COUNT", "ID", "FLAG"}
OPS = {"eq", "ne", "lt", "le", "gt", "ge"}
INT_MIN = -2147483648
INT_MAX = 2147483647

NAME_RE = re.compile(r'^[a-z][a-z0-9_]{0,31}$')
IDVAL_RE = re.compile(r'^[A-Za-z0-9_.:-]{1,32}$')
IDSRC_RE = re.compile(r'^[A-Za-z][A-Za-z0-9_-]{0,31}$')


class SchemaError(Exception):
    pass


class DuplicateKeyError(Exception):
    pass


def emit(obj):
    sys.stdout.write(json.dumps(obj, separators=(',', ':')))
    sys.stdout.flush()


def is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)


def is_s32(x):
    return is_int(x) and INT_MIN <= x <= INT_MAX


def is_bool(x):
    return isinstance(x, bool)


# ---------------- JSON strictness ----------------

def _hook(pairs):
    d = {}
    for k, v in pairs:
        if k in d:
            raise DuplicateKeyError(k)
        d[k] = v
    return d


def _pconst(s):
    raise ValueError("nonfinite constant")


def has_nonfinite(x):
    stack = [x]
    while stack:
        v = stack.pop()
        if isinstance(v, float):
            if not math.isfinite(v):
                return True
        elif isinstance(v, dict):
            stack.extend(v.values())
        elif isinstance(v, list):
            stack.extend(v)
    return False


def max_container_depth(x):
    stack = [(x, 1)]
    md = 0
    while stack:
        v, d = stack.pop()
        if isinstance(v, (dict, list)):
            if d > md:
                md = d
            nd = d + 1
            if isinstance(v, dict):
                for val in v.values():
                    stack.append((val, nd))
            else:
                for val in v:
                    stack.append((val, nd))
    return md


# ---------------- schema/request validation ----------------

def validate_request(data):
    if not isinstance(data, dict):
        raise SchemaError()
    required = {"version", "schema", "window", "atoms", "policy", "train", "probes", "queries"}
    if set(data.keys()) != required:
        raise SchemaError()

    # version
    if not (is_int(data["version"]) and data["version"] == 1):
        raise SchemaError()

    # window
    K = data["window"]
    if not (is_int(K) and 1 <= K <= 8):
        raise SchemaError()

    # schema
    schema = data["schema"]
    if not isinstance(schema, list) or not (1 <= len(schema) <= 32):
        raise SchemaError()
    fields = []  # list of dicts name,type,index,...
    fieldmap = {}
    names = set()
    for i, f in enumerate(schema):
        if not isinstance(f, dict):
            raise SchemaError()
        typ = f.get("type")
        if typ in NUMERIC:
            if set(f.keys()) != {"name", "type", "min", "max"}:
                raise SchemaError()
            name = f["name"]
            if not isinstance(name, str) or not NAME_RE.match(name):
                raise SchemaError()
            lo = f["min"]; hi = f["max"]
            if not (is_s32(lo) and is_s32(hi) and lo <= hi):
                raise SchemaError()
            if name in names:
                raise SchemaError()
            names.add(name)
            fieldmap[name] = {"index": i, "type": typ, "min": lo, "max": hi}
            fields.append(fieldmap[name])
        elif typ == "ID":
            if set(f.keys()) != {"name", "type", "values"}:
                raise SchemaError()
            name = f["name"]
            if not isinstance(name, str) or not NAME_RE.match(name):
                raise SchemaError()
            vals = f["values"]
            if not isinstance(vals, list) or not (1 <= len(vals) <= 32):
                raise SchemaError()
            vset = set()
            for v in vals:
                if not isinstance(v, str) or not IDVAL_RE.match(v):
                    raise SchemaError()
                if v in vset:
                    raise SchemaError()
                vset.add(v)
            if name in names:
                raise SchemaError()
            names.add(name)
            fieldmap[name] = {"index": i, "type": typ, "values": vset}
            fields.append(fieldmap[name])
        elif typ == "FLAG":
            if set(f.keys()) != {"name", "type"}:
                raise SchemaError()
            name = f["name"]
            if not isinstance(name, str) or not NAME_RE.match(name):
                raise SchemaError()
            if name in names:
                raise SchemaError()
            names.add(name)
            fieldmap[name] = {"index": i, "type": typ}
            fields.append(fieldmap[name])
        else:
            raise SchemaError()

    # atoms
    atoms = data["atoms"]
    if not isinstance(atoms, list) or not (0 <= len(atoms) <= 20):
        raise SchemaError()
    for atom in atoms:
        validate_atom(atom, K, fieldmap)

    # policy
    policy = data["policy"]
    if not isinstance(policy, dict) or set(policy.keys()) != {"max_width", "min_support", "min_witness"}:
        raise SchemaError()
    B = policy["max_width"]
    S = policy["min_support"]
    W = policy["min_witness"]
    if not (is_int(B) and 1 <= B <= 4):
        raise SchemaError()
    if not (is_int(S) and 1 <= S <= 4096):
        raise SchemaError()
    if not (is_int(W) and 1 <= W <= 4096):
        raise SchemaError()

    # traces
    seen_ids = set()
    total_rows = 0
    total_traces = 0

    def parse_partition(arr):
        nonlocal total_rows, total_traces
        if not isinstance(arr, list):
            raise SchemaError()
        total_traces += len(arr)
        traces = []
        for tr in arr:
            if not isinstance(tr, dict) or set(tr.keys()) != {"id", "source", "rows"}:
                raise SchemaError()
            tid = tr["id"]; src = tr["source"]; rows = tr["rows"]
            if not isinstance(tid, str) or not IDSRC_RE.match(tid):
                raise SchemaError()
            if not isinstance(src, str) or not IDSRC_RE.match(src):
                raise SchemaError()
            if tid in seen_ids:
                raise SchemaError()
            seen_ids.add(tid)
            if not isinstance(rows, list):
                raise SchemaError()
            total_rows += len(rows)
            times = set()
            prow = []
            for r in rows:
                if not isinstance(r, dict) or set(r.keys()) != {"t", "values"}:
                    raise SchemaError()
                t = r["t"]
                if not is_s32(t):
                    raise SchemaError()
                if t in times:
                    raise SchemaError()
                times.add(t)
                vals = r["values"]
                if not isinstance(vals, list) or len(vals) != len(fields):
                    raise SchemaError()
                for fi, v in enumerate(vals):
                    fd = fields[fi]
                    typ = fd["type"]
                    if typ in NUMERIC:
                        if not is_int(v) or not (fd["min"] <= v <= fd["max"]):
                            raise SchemaError()
                    elif typ == "ID":
                        if not isinstance(v, str) or v not in fd["values"]:
                            raise SchemaError()
                    else:  # FLAG
                        if not is_bool(v):
                            raise SchemaError()
                prow.append({"t": t, "values": list(vals)})
            traces.append({"id": tid, "source": src, "rows": prow})
        return traces

    train = parse_partition(data["train"])
    probes = parse_partition(data["probes"])
    queries = parse_partition(data["queries"])

    if total_traces > 128:
        raise SchemaError()
    if total_rows > 16384:
        raise SchemaError()

    train_sources_set = set()
    for tr in train:
        train_sources_set.add(tr["source"])
    if len(train_sources_set) > 16:
        raise SchemaError()

    return {
        "K": K,
        "fields": fields,
        "fieldmap": fieldmap,
        "atoms": atoms,
        "B": B, "S": S, "W": W,
        "train": train, "probes": probes, "queries": queries,
        "train_sources": list(dict.fromkeys(tr["source"] for tr in train)),
    }


def validate_atom(atom, K, fieldmap):
    if not isinstance(atom, dict):
        raise SchemaError()
    ks = set(atom.keys())
    if ks == {"quantifier", "from", "to", "predicate"}:
        q = atom["quantifier"]
        if q not in ("any", "all"):
            raise SchemaError()
        A = atom["from"]; Z = atom["to"]
        if not (is_int(A) and is_int(Z) and 0 <= A <= Z < K):
            raise SchemaError()
        pred = atom["predicate"]
        if not isinstance(pred, dict):
            raise SchemaError()
        validate_comparison(pred, K, fieldmap, allow_dollar=True)
    else:
        validate_comparison(atom, K, fieldmap, allow_dollar=False)


def validate_comparison(node, K, fieldmap, allow_dollar):
    if not isinstance(node, dict) or set(node.keys()) != {"cmp", "left", "right"}:
        raise SchemaError()
    op = node["cmp"]
    if op not in OPS:
        raise SchemaError()
    lt, ld, ln = validate_term(node["left"], K, fieldmap, allow_dollar)
    rt, rd, rn = validate_term(node["right"], K, fieldmap, allow_dollar)
    if lt != rt:
        raise SchemaError()
    if lt in ("ID", "FLAG") and op not in ("eq", "ne"):
        raise SchemaError()
    if ln + rn > 64:
        raise SchemaError()
    if max(ld, rd) > 4:
        raise SchemaError()


def validate_term(term, K, fieldmap, allow_dollar):
    if not isinstance(term, dict):
        raise SchemaError()
    ks = set(term.keys())
    if ks == {"field", "at"}:
        name = term["field"]
        if not isinstance(name, str) or name not in fieldmap:
            raise SchemaError()
        at = term["at"]
        if is_int(at):
            if not (0 <= at < K):
                raise SchemaError()
        elif at == "$":
            if not allow_dollar:
                raise SchemaError()
        else:
            raise SchemaError()
        return (fieldmap[name]["type"], 1, 1)
    if ks == {"const", "type"}:
        typ = term["type"]
        if typ not in ALLTYPES:
            raise SchemaError()
        v = term["const"]
        if typ in NUMERIC:
            if not is_s32(v):
                raise SchemaError()
        elif typ == "ID":
            if not isinstance(v, str) or not IDVAL_RE.match(v):
                raise SchemaError()
        else:  # FLAG
            if not is_bool(v):
                raise SchemaError()
        return (typ, 1, 1)
    if ks == {"scale", "term"}:
        s = term["scale"]
        if not (is_int(s) and -1024 <= s <= 1024):
            raise SchemaError()
        t, d, n = validate_term(term["term"], K, fieldmap, allow_dollar)
        if t not in NUMERIC:
            raise SchemaError()
        d += 1
        if d > 4:
            raise SchemaError()
        return (t, d, 1 + n)
    if ks == {"add"}:
        arr = term["add"]
        if not isinstance(arr, list) or len(arr) != 2:
            raise SchemaError()
        t1, d1, n1 = validate_term(arr[0], K, fieldmap, allow_dollar)
        t2, d2, n2 = validate_term(arr[1], K, fieldmap, allow_dollar)
        if t1 != t2:
            raise SchemaError()
        if t1 not in NUMERIC:
            raise SchemaError()
        d = max(d1, d2) + 1
        if d > 4:
            raise SchemaError()
        return (t1, d, 1 + n1 + n2)
    if ks == {"aggregate", "field", "from", "to"}:
        op = term["aggregate"]
        if op not in ("sum", "mean", "min", "max"):
            raise SchemaError()
        name = term["field"]
        if not isinstance(name, str) or name not in fieldmap:
            raise SchemaError()
        if fieldmap[name]["type"] not in NUMERIC:
            raise SchemaError()
        f = term["from"]; tto = term["to"]
        if not (is_int(f) and is_int(tto) and 0 <= f <= tto < K):
            raise SchemaError()
        return (fieldmap[name]["type"], 1, 1)
    raise SchemaError()


# ---------------- evaluation ----------------

def eval_term(term, rowvals, binding, fieldmap):
    if "aggregate" in term:
        fd = fieldmap[term["field"]]
        fi = fd["index"]
        f = term["from"]; tto = term["to"]
        vals = [rowvals[o][fi] for o in range(f, tto + 1)]
        op = term["aggregate"]
        if op == "sum":
            return sum(vals)
        if op == "mean":
            return Fraction(sum(vals), len(vals))
        if op == "min":
            return min(vals)
        return max(vals)
    if "field" in term:
        fd = fieldmap[term["field"]]
        at = term["at"]
        off = binding if at == "$" else at
        return rowvals[off][fd["index"]]
    if "const" in term:
        return term["const"]
    if "scale" in term:
        return term["scale"] * eval_term(term["term"], rowvals, binding, fieldmap)
    # add
    arr = term["add"]
    return eval_term(arr[0], rowvals, binding, fieldmap) + eval_term(arr[1], rowvals, binding, fieldmap)


def apply_op(op, l, r):
    if op == "eq":
        return l == r
    if op == "ne":
        return l != r
    if op == "lt":
        return l < r
    if op == "le":
        return l <= r
    if op == "gt":
        return l > r
    return l >= r


def eval_comparison(node, rowvals, binding, fieldmap):
    l = eval_term(node["left"], rowvals, binding, fieldmap)
    r = eval_term(node["right"], rowvals, binding, fieldmap)
    return apply_op(node["cmp"], l, r)


def eval_atom(atom, rowvals, fieldmap):
    if "quantifier" in atom:
        A = atom["from"]; Z = atom["to"]
        pred = atom["predicate"]
        if atom["quantifier"] == "any":
            for o in range(A, Z + 1):
                if eval_comparison(pred, rowvals, o, fieldmap):
                    return True
            return False
        else:
            for o in range(A, Z + 1):
                if not eval_comparison(pred, rowvals, o, fieldmap):
                    return False
            return True
    return eval_comparison(atom, rowvals, None, fieldmap)


# ---------------- contexts ----------------

def build_contexts(traces, K):
    out = []
    for tr in traces:
        rows = sorted(tr["rows"], key=lambda r: r["t"])
        n = len(rows)
        for end in range(K - 1, n):
            window = rows[end - K + 1:end + 1]
            out.append({
                "values": [r["values"] for r in window],
                "trace": tr["id"],
                "end": rows[end]["t"],
                "source": tr["source"],
            })
    return out


def build_atom_masks(contexts, atoms, fieldmap):
    masks = [0] * len(atoms)
    for ci, ctx in enumerate(contexts):
        cv = ctx["values"]
        bit = 1 << ci
        for ai, atom in enumerate(atoms):
            if eval_atom(atom, cv, fieldmap):
                masks[ai] |= bit
    return masks


# ---------------- clause mining ----------------

def mine(model):
    K = model["K"]
    atoms = model["atoms"]
    fieldmap = model["fieldmap"]
    B = model["B"]; S = model["S"]; W = model["W"]

    train_contexts = build_contexts(model["train"], K)
    probe_contexts = build_contexts(model["probes"], K)
    query_contexts = build_contexts(model["queries"], K)

    if len(train_contexts) > 4096:
        raise SchemaError()
    if len(probe_contexts) > 128:
        raise SchemaError()
    if len(query_contexts) > 1024:
        raise SchemaError()

    train_sources = model["train_sources"]

    # Condition 1: at least one training source and at least one probe context.
    result = {
        "classes": [],
        "queries": [],
    }

    if len(train_sources) == 0 or len(probe_contexts) == 0:
        # no eligible clauses; still answer queries
        result["queries"] = answer_queries({}, {}, query_contexts)
        return result

    train_masks = build_atom_masks(train_contexts, atoms, fieldmap)
    probe_masks = build_atom_masks(probe_contexts, atoms, fieldmap)
    query_masks = build_atom_masks(query_contexts, atoms, fieldmap)

    NT = len(train_contexts)
    full_train = (1 << NT) - 1
    P = len(probe_contexts)
    full_probe = (1 << P) - 1
    Q = len(query_contexts)
    full_query = (1 << Q) - 1

    # source masks over training contexts
    src_masks = {s: 0 for s in train_sources}
    for ci, ctx in enumerate(train_contexts):
        src_masks[ctx["source"]] |= (1 << ci)

    A = len(atoms)
    lit_train = {}
    lit_probe = {}
    lit_query = {}
    usable_pols = {}

    for a in range(A):
        pols = []
        for neg in (False, True):
            tm = train_masks[a] if not neg else (full_train ^ train_masks[a])
            ok = True
            for s in train_sources:
                if (tm & src_masks[s]).bit_count() < S:
                    ok = False
                    break
            if ok:
                pols.append(neg)
                lit_train[(a, neg)] = tm
                lit_probe[(a, neg)] = probe_masks[a] if not neg else (full_probe ^ probe_masks[a])
                lit_query[(a, neg)] = query_masks[a] if not neg else (full_query ^ query_masks[a])
        if pols:
            usable_pols[a] = pols

    atoms_usable = list(usable_pols.keys())

    classes = {}

    for w in range(1, B + 1):
        if w > len(atoms_usable):
            break
        for combo in combinations(atoms_usable, w):
            pol_options = [usable_pols[a] for a in combo]
            for signs in product(*pol_options):
                lits = tuple((combo[i], signs[i]) for i in range(w))
                # condition 3
                ORall = 0
                for lit in lits:
                    ORall |= lit_train[lit]
                if ORall != full_train:
                    continue
                # condition 5
                ORprobe = 0
                for lit in lits:
                    ORprobe |= lit_probe[lit]
                if ORprobe == full_probe:
                    continue
                # condition 4
                ok = True
                for i in range(w):
                    others = 0
                    for j in range(w):
                        if j != i:
                            others |= lit_train[lits[j]]
                    wit = lit_train[lits[i]] & (full_train ^ others)
                    for s in train_sources:
                        if (wit & src_masks[s]).bit_count() < W:
                            ok = False
                            break
                    if not ok:
                        break
                if not ok:
                    continue
                d = classes.get(ORprobe)
                if d is None:
                    d = {"count": 0, "rep": lits, "members": []}
                    classes[ORprobe] = d
                d["count"] += 1
                d["members"].append(lits)

    # build output classes
    out_classes = []
    for sig, d in classes.items():
        out_classes.append({
            "signature": format_signature(sig, P),
            "members": d["count"],
            "representative": {"or": [{"atom": a, "negated": neg} for (a, neg) in d["rep"]]},
        })

    result["classes"] = out_classes
    result["queries"] = answer_queries(classes, lit_query, query_contexts)
    return result


def format_signature(sig, P):
    width = (P + 3) // 4
    if width == 0:
        return ""
    h = format(sig, "x")
    if len(h) < width:
        h = h.rjust(width, "0")
    return h


def answer_queries(classes, lit_query, query_contexts):
    Q = len(query_contexts)
    if Q == 0:
        return []
    full_q = (1 << Q) - 1

    # Aggregate identical (all_false, some_false) mask pairs.
    agg = {}
    for sig, d in classes.items():
        all_false = full_q
        some_false = 0
        for lits in d["members"]:
            cm = 0
            for lit in lits:
                cm |= lit_query[lit]
            nf = full_q ^ cm
            all_false &= nf
            some_false |= nf
            if all_false == 0 and some_false == full_q:
                break
        key = (all_false, some_false)
        agg[key] = agg.get(key, 0) + 1

    M = [0] * Q
    Y = [0] * Q
    for (af, sf), cnt in agg.items():
        m = af
        while m:
            lsb = m & -m
            idx = lsb.bit_length() - 1
            M[idx] += cnt
            m ^= lsb
        s = sf
        while s:
            lsb = s & -s
            idx = lsb.bit_length() - 1
            Y[idx] += cnt
            s ^= lsb

    out = []
    for j, ctx in enumerate(query_contexts):
        if M[j] > 0:
            status = "violating"
        elif Y[j] > 0:
            status = "ambiguous"
        else:
            status = "consistent"
        out.append({
            "trace": ctx["trace"],
            "end": ctx["end"],
            "must": M[j],
            "may": Y[j],
            "status": status,
        })
    return out


def solve(data):
    model = validate_request(data)
    return mine(model)


def main():
    raw = sys.stdin.buffer.read()
    if len(raw) > MAXBYTES:
        emit({"error": "E_LIMIT"})
        return
    if raw[:3] == b"\xef\xbb\xbf":
        emit({"error": "E_JSON"})
        return
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        emit({"error": "E_JSON"})
        return
    try:
        data = json.loads(text, object_pairs_hook=_hook, parse_constant=_pconst)
    except (json.JSONDecodeError, ValueError, RecursionError, DuplicateKeyError):
        emit({"error": "E_JSON"})
        return
    if has_nonfinite(data):
        emit({"error": "E_JSON"})
        return
    try:
        if max_container_depth(data) > 64:
            emit({"error": "E_JSON"})
            return
    except RecursionError:
        emit({"error": "E_JSON"})
        return
    try:
        resp = solve(data)
    except SchemaError:
        emit({"error": "E_SCHEMA"})
        return
    except RecursionError:
        emit({"error": "E_JSON"})
        return
    emit(resp)


if __name__ == "__main__":
    main()
